def specialties_to_areas(apps, schema_editor):
    # dispute types -> Art. 3 areas: mehnat and oilaviy keep their name, the rest are civil (fuqarolik)
    Mediator = apps.get_model("mediators", "Mediator")
    for m in Mediator.objects.all():
        areas = sorted({t if t in ("mehnat", "oilaviy") else "fuqarolik" for t in (m.specialties or [])})
        Mediator.objects.filter(pk=m.pk).update(areas=areas or ["fuqarolik"])


